const categories=[{id:'it',name:'IT น่ารู้',en:'TECH & GADGETS',desc:'เทคโนโลยีใกล้ตัว ที่ทำให้ทุกวันน่าสนใจขึ้น',color:'#e6e9df',icon:'⌘'},{id:'apple',name:'โลกของ Apple',en:'APPLE JOURNAL',desc:'ติดตามข่าวและแนวคิดในโลกของ Apple อย่างมีที่มา',color:'#e2e4e4',icon:'◉'},{id:'skin',name:'ดูแลตัวเอง',en:'SKIN & SELF-CARE',desc:'ค่อย ๆ ทำความเข้าใจผิว และให้เวลากับตัวเอง',color:'#e8dfd8',icon:'◌'},{id:'style',name:'แบรนด์ไทย',en:'THAI STYLE',desc:'เรื่องของดีไซน์ วัสดุ และความคิดสร้างสรรค์ใกล้บ้าน',color:'#e1e1d8',icon:'〰'}];
const stories=[{id:'desk',cat:'it',title:'มุมทำงานที่ชอบ เริ่มจากสิ่งเล็ก ๆ บนโต๊ะ',desc:'สำรวจวิธีจัดพื้นที่ให้เข้ากับชีวิต ก่อนเพิ่มแกดเจ็ตชิ้นต่อไป',read:4,section:'พื้นที่ที่ทำให้เราอยากกลับมานั่ง',body:['ต้นแบบบทความนี้ชวนเริ่มจากการสังเกตวิธีใช้โต๊ะของตัวเอง งานที่ทำบ่อย พื้นที่ที่ต้องการ และสิ่งที่หยิบใช้ทุกวัน เป็นโจทย์ก่อนเลือกอุปกรณ์','ลองแบ่งพื้นที่เป็นส่วนทำงาน ส่วนพักสายตา และที่เก็บของ แล้วค่อยพิจารณาว่าอุปกรณ์ใหม่ช่วยแก้ปัญหาตรงไหนจริง ๆ บ้าง'],checks:['ตรวจชื่อรุ่นและสเปกกับผู้ผลิต','ระบุวันที่ตรวจราคาและเงื่อนไข','แยกข้อมูลผู้ผลิตออกจากประสบการณ์ทดลองจริง']},{id:'apple-journal',cat:'apple',title:'ข่าวจริง ข่าวลือ หรือแค่คอนเซปต์? อ่านโลก Apple ให้ชัดขึ้น',desc:'พื้นที่สำหรับข่าวที่ตรวจสอบย้อนกลับได้ พร้อมแยกสถานะข้อมูล',read:3,section:'อ่านที่มา ก่อนอ่านความตื่นเต้น',body:['หน้า Apple ของเราจะจัดข่าวตามสถานะ เช่น ประกาศทางการ รายงานจากสื่อ และข่าวลือ เพื่อให้ผู้อ่านเห็นว่าข้อความแต่ละส่วนยืนยันได้แค่ไหน','เอกสารจาก Drive เป็นวัตถุดิบสำหรับทำงาน ยังไม่ถือเป็นหลักฐานยืนยันการเปิดตัวสินค้า ข่าวที่ระบุวัน สเปก หรือราคา ต้องตรวจเทียบกับแหล่งต้นฉบับก่อนขึ้นเว็บ'],checks:['ลิงก์ประกาศหรือเอกสารต้นฉบับ','วันที่เกิดเหตุการณ์และวันที่รายงาน','ระบุข่าวลืออย่างชัดเจน ไม่ใช้เป็นข่าวยืนยัน']},{id:'skin-notes',cat:'skin',title:'อ่านฉลากให้เป็น แล้วค่อยเลือกสิ่งที่เหมาะกับเรา',desc:'บันทึกความสนใจเรื่องส่วนผสม โดยเริ่มจากคำถามและหลักฐาน',read:5,section:'ความเข้าใจเล็ก ๆ ก่อนเติมขั้นตอนใหม่',body:['พื้นที่นี้ออกแบบสำหรับบทความความรู้เรื่องสกินแคร์ โดยไม่เปลี่ยนคำโฆษณาให้กลายเป็นข้อสรุปทางการแพทย์','ก่อนเผยแพร่เนื้อหาจริง เราจะตรวจแหล่งงานวิจัย ประชากรที่ศึกษา สูตรผลิตภัณฑ์ และข้อจำกัดของข้อมูล ไม่ใช้ผลจากสารเดี่ยวรับประกันผลของผลิตภัณฑ์ทั้งสูตร'],checks:['ตรวจงานวิจัยต้นฉบับและบริบท','ไม่รับประกันผลหรือความปลอดภัยเฉพาะบุคคล','แยกความรู้ทั่วไปจากคำแนะนำรักษาโรค']},{id:'thai-fabric',cat:'style',title:'รู้จักแบรนด์ไทย ผ่านเนื้อผ้าและรายละเอียด',desc:'มองให้ไกลกว่าโลโก้ แล้วค้นหาเสื้อผ้าที่เข้ากับชีวิตประจำวัน',read:4,section:'ดีไซน์ที่เริ่มจากคำถามว่าใส่อย่างไร',body:['บทความตัวอย่างนี้เสนอวิธีเล่าเรื่องแบรนด์ไทยผ่านวัสดุ รูปทรง และแนวคิด โดยใช้ภาพนามธรรมที่เราสร้างขึ้นเอง','หน้าจริงจะอ้างอิงข้อมูลวัสดุและเงื่อนไขจากแบรนด์ พร้อมแยกความเห็นบรรณาธิการออกจากข้อเท็จจริง ไม่สร้างคะแนนรีวิวหรืออ้างว่าเคยสวมใส่หากไม่มีการทดสอบ'],checks:['ระบุแหล่งข้อมูลวัสดุและผู้ผลิต','ใช้รูปที่มีสิทธิ์เผยแพร่เท่านั้น','ไม่อ้างประสบการณ์ใช้งานที่ไม่ได้เกิดขึ้น']},{id:'quiet-tech',cat:'it',title:'เทคโนโลยีที่ดี อาจทำให้เรามองจอน้อยลง',desc:'ชวนคิดถึงอุปกรณ์ที่ช่วยลดความวุ่นวาย มากกว่าเพิ่มการแจ้งเตือน',read:3,section:'ออกแบบให้ชีวิตมีที่ว่าง',body:['ไอเดียสำหรับบทความเชิงมุมมองของเว็บไซต์: ชวนตั้งคำถามว่าอุปกรณ์แต่ละชิ้นทำให้ชีวิตง่ายขึ้นจริงหรือเพิ่มภาระดูแล','ต้นแบบนี้ยังไม่เป็นการแนะนำซื้อสินค้า เราจะเติมข้อมูลที่ตรวจสอบแล้วก่อนเผยแพร่รีวิวหรือเปรียบเทียบรุ่นจริง'],checks:['กำหนดเกณฑ์เปรียบเทียบที่อธิบายได้','เปิดเผยสปอนเซอร์หรือความสัมพันธ์ทางการค้า','ไม่อ้างว่าเป็นเทรนด์ล่าสุดโดยไม่มีหลักฐาน']},{id:'daily-pause',cat:'skin',title:'เว้นที่ว่างเล็ก ๆ ให้ตัวเองในทุกวัน',desc:'ความสนใจเรื่องการดูแลตัวเอง ที่ไม่ต้องเริ่มจากการซื้อเพิ่ม',read:2,section:'บันทึกความสนใจ ไม่ใช่สูตรสำเร็จ',body:['บางครั้งบทความที่เราอยากอ่านคือเรื่องเล็ก ๆ ที่ทำให้หยุดพักและสังเกตตัวเอง เว็บไซต์นี้จึงมีพื้นที่สำหรับเรื่องเล่าและมุมมองที่เขียนขึ้นใหม่','เนื้อหาประเภทนี้จะระบุว่าเป็นมุมมองบรรณาธิการ และไม่ใช้แทนคำแนะนำส่วนบุคคลจากผู้เชี่ยวชาญ'],checks:['แยกความเห็นออกจากข้อเท็จจริง','ไม่ใช้ภาพหรือคำรับรองจากบุคคลอื่นโดยไม่มีสิทธิ์','แสดงวันที่และที่มาของข้อมูลเมื่อมีการอ้างอิง']}];
const $=s=>document.querySelector(s),cat=id=>categories.find(c=>c.id===id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[];try{saved=JSON.parse(localStorage.getItem('chob-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;let filter='all',query='',savedOnly=false;let toastTimer;const art=(c,cls='')=>`<div class="art ${cls}" aria-hidden="true"><div class="object obj-${c.id}"></div></div>`;
function scene(){return `<div class="scene" aria-hidden="true"><div class="scene-grid"></div><div class="sculpture"><div class="chrome ring"></div><div class="chrome ring two"></div><div class="chrome sphere"></div></div><div class="floating-tag tag-one"><span class="tag-icon">⌘</span><span>A LITTLE TECH</span><b>ไอเดียใหม่ทุกวัน</b></div><div class="floating-tag tag-two"><span class="tag-icon">◌</span><span>A LITTLE SELF-CARE</span><b>ดูแลโลกใบเล็กของเรา</b></div><div class="floating-tag tag-three"><span class="tag-icon">〰</span><span>A LITTLE STYLE</span><b>ดีไซน์ที่มีเรื่องเล่า</b></div><div class="round-note">✳</div><span class="scene-label">OBJECT NO. 001 / CURIOSITY IN ORBIT</span></div>`}
function card(s){const c=cat(s.cat);return `<article class="story"><a href="#/article/${s.id}" aria-label="อ่าน ${esc(s.title)}"><div class="story-visual cat-${c.id}">${art(c)}<span class="visual-text">${c.en} / ORIGINAL ARTWORK</span></div></a><div class="story-top"><a class="category" href="#/category/${c.id}">${c.en}</a><span class="status">บทความตัวอย่าง</span></div><h3><a href="#/article/${s.id}">${s.title}</a></h3><p>${s.desc}</p><div class="story-bottom"><span>ฉบับต้นแบบ · ${s.read} นาที</span><button class="bookmark" data-save="${s.id}" aria-label="${saved.includes(s.id)?'ยกเลิกบันทึก':'บันทึก'} ${esc(s.title)}" aria-pressed="${saved.includes(s.id)}">${saved.includes(s.id)?'♥':'♡'}</button></div></article>`}
function filterBar(withCats=true){return `<div class="filters">${withCats?`<button class="chip ${filter==='all'?'active':''}" data-filter="all">ทั้งหมด</button>${categories.map(c=>`<button class="chip ${filter===c.id?'active':''}" data-filter="${c.id}">${c.name}</button>`).join('')}`:''}<label class="search"><span class="sr-only">ค้นหาบทความ</span><input id="search" type="search" placeholder="ค้นหาเรื่องที่สนใจ ↗" value="${esc(query)}"></label></div>`}
function visible(items=stories){return items.filter(s=>(filter==='all'||s.cat===filter)&&(!savedOnly||saved.includes(s.id))&&`${s.title} ${s.desc} ${cat(s.cat).name}`.toLowerCase().includes(query.toLowerCase()))}
function grid(items=stories){const v=visible(items);return v.length?v.map(card).join(''):`<div class="empty">${savedOnly?'ยังไม่มีเรื่องที่บันทึกไว้ กด ♡ ที่บทความเพื่อเก็บไว้อ่าน':'ไม่พบเรื่องที่ค้นหา ลองเปลี่ยนคำค้นหรือหมวดหมู่ครับ'}</div>`}
function listing(title='เรื่องที่อยากเล่าต่อ',items=stories){return `<section class="section" id="stories"><div class="section-head"><div><div class="eyebrow">THE READING ROOM</div><h2>${title}</h2></div><span class="eyebrow">CURATED WITH CARE ↙</span></div>${filterBar(items===stories)}<div class="filter-note">เนื้อหาตัวอย่างที่เขียนสำหรับต้นแบบ · ยังไม่ใช่ข่าวหรือคำแนะนำสินค้าที่ตรวจยืนยันแล้ว</div><div class="article-grid" id="article-grid">${grid(items)}</div></section>`}
function home(){return `<div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> YOUR DAILY DOSE OF CURIOSITY</div><h1>ชอบอะไร<br>ก็<span class="hero-accent">ไปเรื่อย.</span></h1><p>เทคโนโลยีที่น่าลอง เรื่องผิวที่อยากรู้<br>และดีไซน์ที่ทำให้เราเผลอหยุดมอง<br>รวมเรื่องที่ชอบไว้ในที่เดียว</p><a class="primary" href="#/archive">หาเรื่องที่ชอบ <span>↗</span></a><div class="hero-bottom"><span class="mini-line"></span><span>4 WORLDS. ENDLESS CURIOSITY.</span></div></div>${scene()}</section></div><div class="ticker"><span>TECH FOR EVERYDAY</span><span>✳</span><span>APPLE & BEYOND</span><span>✳</span><span>FEEL GOOD IN YOUR SKIN</span><span>✳</span><span>LOCAL IS LOVELY</span></div><div class="wrap"><section class="section"><div class="section-head"><div><div class="eyebrow">PICK YOUR LITTLE WORLD</div><h2>วันนี้อยากชอบอะไร?</h2></div><span class="eyebrow">01 — 04</span></div><div class="category-grid">${categories.map((c,i)=>`<a class="category-card cat-${c.id}" href="#/category/${c.id}">${art(c)}<div class="category-info"><div><small>0${i+1} / ${c.en}</small><h3>${c.name}</h3></div><span class="circle-arrow">↗</span></div></a>`).join('')}</div></section>${listing()}<aside class="manifesto"><span>✳</span><div><h2>ความชอบเปลี่ยนได้ ความสงสัยอยู่เสมอ</h2><p>พื้นที่อิสระสำหรับคนที่อยากรู้เพิ่มอีกนิด<br>เล่าใหม่ด้วยภาษาของเรา และให้เครดิตกับทุกที่มา</p></div><a href="#/about">รู้จักพื้นที่นี้ ↗</a></aside></div>`}
function categoryPage(c){return `<div class="wrap"><section class="category-hero"><div class="page-heading"><div class="eyebrow">THE CURIOSITY CLUB / ${c.en}</div><h1>${c.name}<span class="heading-dot">.</span></h1><p>${c.desc}</p><a class="back" href="#/">← กลับไปสำรวจโลกอื่น</a></div>${art(c)}</section>${listing('บันทึกจากโลกใบนี้',stories.filter(s=>s.cat===c.id))}</div>`}
function archive(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">GOOD THINGS ARE WORTH KEEPING</div><h1>${savedOnly?'เรื่องที่เก็บไว้ชอบ':'คลังเรื่องที่ชอบ'}.</h1><p>ค้นหา เลือกหมวด หรือกลับมาอ่านเรื่องเดิมในวันที่อยากรู้เพิ่มอีกนิด</p></div>${listing(savedOnly?'ชั้นหนังสือของคุณ':'เรื่องทั้งหมด')}<section class="section"><div class="section-head"><div><div class="eyebrow">FROM YOUR GOOGLE DRIVE</div><h2>คลังต้นฉบับ</h2></div><select id="archive-category" class="archive-select" aria-label="เลือกหมวดเอกสารต้นฉบับ"><option value="all">ทุกหมวด</option>${categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div><p class="filter-note">เวอร์ชันโค้ดสาธารณะไม่รวมรายการเอกสารส่วนตัว · ยังไม่เชื่อม Drive อัตโนมัติ</p><div id="drive-list"></div><button class="chip" id="more-drive" hidden>ดูเพิ่ม</button></section></div>`}
function article(s){const c=cat(s.cat);return `<article class="article-layout"><a class="back" href="#/category/${c.id}">← ${c.name}</a><div class="eyebrow">${c.en} / EDITORIAL PROTOTYPE</div><h1>${s.title}</h1><div class="story-top"><span>ต้นฉบับเขียนสำหรับเว็บไซต์ · อ่าน ${s.read} นาที</span><button class="bookmark" data-save="${s.id}" aria-label="บันทึกเรื่องนี้" aria-pressed="${saved.includes(s.id)}">${saved.includes(s.id)?'♥':'♡'}</button></div><div class="story-visual cat-${c.id}">${art(c)}<span class="visual-text">ORIGINAL PROCEDURAL ARTWORK</span></div><div class="notice"><strong>บทความตัวอย่างสำหรับทดลองหน้าตาเว็บ</strong><br>ไม่ใช่ข่าวสด รีวิวจากการทดสอบ หรือคำแนะนำเฉพาะบุคคล เนื้อหาจริงจาก Drive จะเข้าสู่ขั้นตอนตรวจสอบก่อนเผยแพร่</div><div class="prose"><h2>${s.section}</h2>${s.body.map(p=>`<p>${p}</p>`).join('')}<h2>ก่อนเรื่องนี้จะพร้อมเผยแพร่</h2><ul>${s.checks.map(p=>`<li>${p}</li>`).join('')}</ul><h2>ที่มาและภาพประกอบ</h2><p>ข้อความตัวอย่างเขียนขึ้นใหม่เพื่ออธิบายรูปแบบเนื้อหาที่ตั้งใจทำ ภาพประกอบสร้างด้วย CSS ภายในโครงการ ไม่มีการดึงรูปสินค้าหรือบทความของสื่อมาแสดง</p><p>สถานะ: ต้นแบบ · ไม่มีการอ้างผลการทดสอบสินค้า · ยังไม่มีวันที่ตรวจยืนยันข่าว</p></div><a class="source-link" href="#/archive">ดูรายการเอกสารต้นฉบับในคลัง ↗</a><div class="section-head"><h2>ชอบต่ออีกนิด</h2></div><div class="article-grid related-grid">${stories.filter(x=>x.id!==s.id).sort((a,b)=>Number(b.cat===s.cat)-Number(a.cat===s.cat)).slice(0,2).map(card).join('')}</div></article>`}
function about(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">A LITTLE MORE CURIOUS, EVERY DAY</div><h1>พื้นที่ของคน<br>ชอบไปเรื่อย<span class="heading-star">✳</span></h1><p>เราเชื่อว่าความสนใจไม่ต้องอยู่ในกล่องเดียว เทคโนโลยี การดูแลตัวเอง และแฟชั่น สามารถอยู่ในโลกใบเดียวกันได้</p></div><div class="about-grid"><section class="about-box"><h2>เล่าใหม่ มีที่มา</h2><p>บทความจริงจะใช้ข้อเท็จจริงที่ตรวจสอบได้ เรียบเรียงด้วยภาษาของเรา และลิงก์กลับแหล่งต้นฉบับ ข่าวลือ ความเห็น และประกาศทางการต้องมีป้ายแยกกันชัดเจน</p></section><section class="about-box"><h2>สร้างภาพของเราเอง</h2><p>ภาพนามธรรมและวัตถุบนต้นแบบสร้างด้วยโค้ด CSS ไม่ใช้ภาพสินค้า โลโก้ หรือคลิปจากบุคคลอื่น สื่อในอนาคตต้องมีหลักฐานสิทธิ์และตรวจเงื่อนไขก่อนเผยแพร่</p></section><section class="about-box"><h2>สถานะต้นแบบ</h2><p>รายการต้นฉบับมาจาก Drive ณ 27 ตุลาคม 2026 แต่ยังไม่เชื่อมซิงก์อัตโนมัติ บทความที่เปิดอ่านบนเว็บเป็นข้อความตัวอย่าง เอกสารในคลังยังไม่ผ่านการตรวจรายไฟล์</p></section><section class="about-box"><h2>อ่านสบายในแบบของคุณ</h2><p>ใช้เมนูเข้าทุกหมวดได้โดยตรง กดปุ่มหยุดภาพเคลื่อนไหวด้านบนได้ตลอด เว็บเคารพการตั้งค่าลดการเคลื่อนไหวของอุปกรณ์ เรื่องที่บันทึกจะเก็บเฉพาะในเบราว์เซอร์นี้</p></section></div><div class="notice">การให้เครดิตหรือใช้ AI เรียบเรียงใหม่ไม่ได้รับประกันสิทธิ์ในการใช้ผลงานของผู้อื่น เราจึงต้องตรวจทั้งต้นทาง เนื้อหา และใบอนุญาตเป็นรายชิ้น</div><a class="source-link" href="https://www.wipo.int/en/web/copyright/faq-copyright" target="_blank" rel="noopener noreferrer">อ่านหลักการลิขสิทธิ์จาก WIPO ↗</a></div>`}
let driveItems=[],driveCategory='all',driveLimit=12;
async function loadDrive(){if(!driveItems.length){try{const r=await fetch('drive-index.json');if(!r.ok)throw Error('fetch');driveItems=await r.json()}catch{if($('#drive-list'))$('#drive-list').innerHTML='<div class="empty">โหลดรายการเอกสารไม่สำเร็จ กรุณาลองใหม่ภายหลัง</div>';return}}renderDrive()}
function renderDrive(){if(!$('#drive-list'))return;if(!driveItems.length){$('#drive-list').innerHTML='<div class="empty">รายการเอกสาร Drive เก็บอยู่ในต้นแบบส่วนตัว และไม่ได้รวมใน repository สาธารณะ</div>';$('#more-drive').hidden=true;return}const items=driveItems.filter(x=>driveCategory==='all'||x.cat===driveCategory);$('#drive-list').innerHTML=items.slice(0,driveLimit).map(x=>`<a class="source-link drive-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(x.title)}<small class="drive-link-meta">${cat(x.cat).name} · รอตรวจสอบก่อนเผยแพร่</small></span><span>↗</span></a>`).join('');$('#more-drive').hidden=driveLimit>=items.length}
function route(){if(location.hash==='#main'){$('#main').focus();return}const p=(location.hash.slice(1)||'/').split('/').filter(Boolean);filter='all';query='';const main=$('#main');let content;if(!p.length){savedOnly=false;content=home()}else if(p[0]==='category'&&cat(p[1])){savedOnly=false;content=categoryPage(cat(p[1]))}else if(p[0]==='article'&&stories.some(x=>x.id===p[1])){savedOnly=false;content=article(stories.find(x=>x.id===p[1]))}else if(p[0]==='archive'){content=archive()}else if(p[0]==='about'){savedOnly=false;content=about()}else{content='<div class="wrap page-heading"><h1>หลงมาอีกโลกแล้ว</h1><a class="primary" href="#/">กลับหน้าแรก ↗</a></div>'}main.innerHTML=content;document.body.classList.toggle('saved-view',savedOnly);document.querySelectorAll('[data-nav]').forEach(a=>{const on=a.dataset.nav===(p[0]||'home');a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=(p[0]==='category'&&cat(p[1])?cat(p[1]).name:p[0]==='article'&&stories.find(x=>x.id===p[1])?stories.find(x=>x.id===p[1]).title:p[0]==='archive'?'คลังเรื่องที่ชอบ':p[0]==='about'?'เรื่องของเรา':'A little more curious.')+' — ชอบไปเรื่อย';window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});if(p[0]==='archive'){driveLimit=12;driveCategory='all';loadDrive()}updateSaved()}
function updateGrid(){const current=(location.hash.slice(1)||'/').split('/').filter(Boolean);const items=current[0]==='category'?stories.filter(s=>s.cat===current[1]):stories;if($('#article-grid'))$('#article-grid').innerHTML=grid(items)}
function updateSaved(){$('#saved-count').textContent=saved.length;document.querySelectorAll('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save);b.textContent=yes?'♥':'♡';b.setAttribute('aria-pressed',String(yes));b.setAttribute('aria-label',(yes?'ยกเลิกบันทึก ':'บันทึก ')+(stories.find(s=>s.id===b.dataset.save)?.title||'เรื่องนี้'))})}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));updateGrid()}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('chob-saved',JSON.stringify(saved));toast(saved.includes(id)?'เก็บเรื่องนี้ไว้แล้ว ♡':'นำออกจากเรื่องที่บันทึกแล้ว')}catch{toast('บันทึกชั่วคราวในหน้านี้ เบราว์เซอร์ไม่อนุญาตให้เก็บถาวร')}updateSaved();if(savedOnly)updateGrid()}if(e.target.closest('#more-drive')){driveLimit+=12;renderDrive()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateGrid()}});document.addEventListener('change',e=>{if(e.target.id==='archive-category'){driveCategory=e.target.value;driveLimit=12;renderDrive()}});
$('#saved').addEventListener('click',()=>{savedOnly=true;if(location.hash==='#/archive')route();else location.hash='/archive'});document.querySelector('[data-nav="archive"]').addEventListener('click',()=>{savedOnly=false;if(location.hash==='#/archive')route()});
function setMotion(){document.body.classList.toggle('paused',paused);$('#motion').textContent=paused?'▷':'Ⅱ';$('#motion').setAttribute('aria-pressed',String(paused));$('#motion').setAttribute('aria-label',paused?'เปิดการเคลื่อนไหว':'หยุดการเคลื่อนไหว')}
$('#motion').addEventListener('click',()=>{paused=!paused;setMotion();toast(paused?'หยุดการเคลื่อนไหวแล้ว':'เปิดการเคลื่อนไหวแล้ว')});matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{paused=e.matches;setMotion()});window.addEventListener('hashchange',route);setMotion();route();
